//! Machine-wide caches (only touched with `--global`). Everything here is
//! re-downloaded or regenerated by the owning tool on next use.

use std::path::{Path, PathBuf};

pub fn caches(home: &Path) -> Vec<(&'static str, PathBuf)> {
    let list: &[(&str, &str)] = &[
        // Xcode / iOS
        ("Xcode DerivedData", "Library/Developer/Xcode/DerivedData"),
        (
            "Xcode iOS DeviceSupport",
            "Library/Developer/Xcode/iOS DeviceSupport",
        ),
        (
            "CoreSimulator caches",
            "Library/Developer/CoreSimulator/Caches",
        ),
        ("CocoaPods cache", "Library/Caches/CocoaPods"),
        (
            "Xcode SwiftUI Previews",
            "Library/Developer/Xcode/UserData/Previews",
        ),
        ("SwiftPM cache", "Library/Caches/org.swift.swiftpm"),
        ("Carthage cache", "Library/Caches/org.carthage.CarthageKit"),
        // Gradle / Android
        ("Gradle caches", ".gradle/caches"),
        ("Gradle wrapper dists", ".gradle/wrapper/dists"),
        ("Gradle daemon logs", ".gradle/daemon"),
        ("Android build cache", ".android/build-cache"),
        ("Android cache", ".android/cache"),
        // Flutter / Dart
        ("Pub cache (hosted packages)", ".pub-cache/hosted"),
        ("Pub cache (git packages)", ".pub-cache/git"),
        // JS
        ("npm cache", ".npm/_cacache"),
        ("Yarn cache (macOS)", "Library/Caches/Yarn"),
        ("Yarn cache (Linux)", ".cache/yarn"),
        ("pnpm store (macOS)", "Library/pnpm/store"),
        ("pnpm store (Linux)", ".local/share/pnpm/store"),
        ("Bun cache", ".bun/install/cache"),
        ("Deno cache", "Library/Caches/deno"),
        ("node-gyp headers", "Library/Caches/node-gyp"),
        ("Electron downloads", "Library/Caches/electron"),
        ("Playwright browsers", "Library/Caches/ms-playwright"),
        ("Cypress binaries", "Library/Caches/Cypress"),
        // JVM
        ("Maven repository", ".m2/repository"),
        // Rust
        ("Cargo registry cache", ".cargo/registry/cache"),
        ("Cargo registry sources", ".cargo/registry/src"),
        ("Cargo git checkouts", ".cargo/git/checkouts"),
        // Python / Go / Homebrew
        ("pip cache (macOS)", "Library/Caches/pip"),
        ("pip cache (Linux)", ".cache/pip"),
        ("uv cache (macOS)", "Library/Caches/uv"),
        ("uv cache (Linux)", ".cache/uv"),
        ("Poetry cache", "Library/Caches/pypoetry"),
        ("Go module cache", "go/pkg/mod"),
        ("Composer cache", "Library/Caches/composer"),
        ("Go build cache (macOS)", "Library/Caches/go-build"),
        ("Go build cache (Linux)", ".cache/go-build"),
        ("Homebrew downloads", "Library/Caches/Homebrew"),
    ];

    list.iter()
        .map(|(label, rel)| (*label, home.join(rel)))
        .filter(|(_, p)| p.symlink_metadata().map(|m| m.is_dir()).unwrap_or(false))
        .collect()
}
